use crate::modules::database::types::type_catalog::{ColumnType, RelationType, TypeCatalog};
use crate::modules::database::types::typescript_block::block;
use crate::modules::database::types::typescript_routines::{enums_section, functions_section};
use crate::modules::database::types::typescript_type::{property_key, typescript_type};

const HEADER: &str =
    "// Generated by NelcotaCloud from the project's public schema. Do not edit by hand.

export type Json =
  | string
  | number
  | boolean
  | null
  | { [key: string]: Json | undefined }
  | Json[]
";

/// Which writes a column takes part in, and how.
enum Shape {
    Row,
    Insert,
    Update,
}

/// The `Database` type of a project: what `createClient<Database>()` of the SDK takes.
pub fn write_typescript(catalog: &TypeCatalog) -> String {
    let tables = section(
        &catalog.relations,
        |relation| relation.is_view == false,
        table_type,
    );
    let views = section(&catalog.relations, |relation| relation.is_view, view_type);
    let functions = functions_section(&catalog.functions);
    let enums = enums_section(&catalog.enums);

    format!(
        "{HEADER}\nexport type Database = {{\n  public: {{\n    Tables: {tables}\n    Views: {views}\n    \
         Functions: {functions}\n    Enums: {enums}\n  }}\n}}\n"
    )
}

fn section(
    relations: &[RelationType],
    is_included: fn(&RelationType) -> bool,
    write: fn(&RelationType) -> String,
) -> String {
    let entries: Vec<String> = relations
        .iter()
        .filter(|relation| is_included(relation))
        .map(|relation| {
            format!(
                "      {}: {}",
                property_key(&relation.name),
                write(relation)
            )
        })
        .collect();

    block(&entries, "    ")
}

fn table_type(relation: &RelationType) -> String {
    let columns = &relation.columns;
    let row = columns_object(columns, &Shape::Row);
    let insert = columns_object(columns, &Shape::Insert);
    let update = columns_object(columns, &Shape::Update);

    format!("{{\n        Row: {row}\n        Insert: {insert}\n        Update: {update}\n      }}")
}

fn view_type(relation: &RelationType) -> String {
    let row = columns_object(&relation.columns, &Shape::Row);

    format!("{{\n        Row: {row}\n      }}")
}

fn columns_object(columns: &[ColumnType], shape: &Shape) -> String {
    let entries: Vec<String> = columns
        .iter()
        .filter_map(|column| column_entry(column, shape))
        .map(|entry| format!("          {entry}"))
        .collect();

    block(&entries, "        ")
}

/// Rows always carry every column; writes leave out generated ones, and only required columns
/// of an insert (not null, no default) lose the `?`.
fn column_entry(column: &ColumnType, shape: &Shape) -> Option<String> {
    let key = property_key(&column.name);
    let value = nullable_type(column);

    match shape {
        Shape::Row => Some(format!("{key}: {value}")),
        _ if column.is_generated => None,
        Shape::Insert if column.nullable == false && column.has_default == false => {
            Some(format!("{key}: {value}"))
        }
        Shape::Insert | Shape::Update => Some(format!("{key}?: {value}")),
    }
}

fn nullable_type(column: &ColumnType) -> String {
    let value = typescript_type(&column.value);

    if column.nullable {
        return format!("{value} | null");
    }

    value
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::modules::database::types::type_catalog::{
        ArgumentType, EnumType, FunctionType, ValueType,
    };

    fn value(name: &str) -> ValueType {
        ValueType {
            name: name.to_owned(),
            is_array: false,
            is_enum: false,
            relation: None,
        }
    }

    fn column(name: &str, type_name: &str) -> ColumnType {
        ColumnType {
            name: name.to_owned(),
            value: value(type_name),
            nullable: false,
            has_default: false,
            is_generated: false,
        }
    }

    fn orders() -> RelationType {
        RelationType {
            name: "orders".to_owned(),
            is_view: false,
            columns: vec![
                ColumnType {
                    has_default: true,
                    ..column("id", "int8")
                },
                column("title", "text"),
                ColumnType {
                    nullable: true,
                    ..column("note", "text")
                },
                ColumnType {
                    has_default: true,
                    is_generated: true,
                    ..column("slug", "text")
                },
            ],
        }
    }

    #[test]
    fn tables_get_row_insert_and_update_shapes() {
        let catalog = TypeCatalog {
            relations: vec![orders()],
            enums: vec![],
            functions: vec![],
        };

        let typescript = write_typescript(&catalog);

        assert!(typescript.contains("Row: {\n          id: number\n          title: string\n          note: string | null\n          slug: string\n        }"));
        assert!(typescript.contains("Insert: {\n          id?: number\n          title: string\n          note?: string | null\n        }"));
        assert!(typescript.contains("Update: {\n          id?: number\n          title?: string\n          note?: string | null\n        }"));
        assert!(typescript.contains("Views: { [_ in never]: never }"));
    }

    #[test]
    fn views_enums_and_function_overloads_are_typed() {
        let view = RelationType {
            is_view: true,
            name: "open_orders".to_owned(),
            ..orders()
        };
        let overload = |argument: &str| FunctionType {
            name: "search".to_owned(),
            arguments: vec![ArgumentType {
                name: argument.to_owned(),
                value: value("text"),
                has_default: false,
            }],
            returns: value("int4"),
            returns_set: true,
        };
        let catalog = TypeCatalog {
            relations: vec![view],
            enums: vec![EnumType {
                name: "status".to_owned(),
                labels: vec!["open".to_owned(), "it's done".to_owned()],
            }],
            functions: vec![overload("term"), overload("prefix")],
        };

        let typescript = write_typescript(&catalog);

        assert!(typescript.contains("Tables: { [_ in never]: never }"));
        assert!(typescript.contains("open_orders: {\n        Row: {"));
        assert!(typescript.contains("status: \"open\" | \"it's done\""));
        assert!(typescript.contains("term: string\n        } | {\n          prefix: string"));
        assert!(typescript.contains("Returns: (number)[]"));
    }
}
